$ui-primary: hsla(215, 100%, 95%, 1); /* #E5F0FF */
$ui-secondary: hsla(215, 75%, 95%, 1); /* #E9F1FC */
$ui-tertiary: hsla(215, 50%, 90%, 1); /* #D9E3F2 */

$ui-modal-overlay: hsla(215, 100%, 65%, 0.9); /* 90% transparent version of motion-primary */
$ui-alert-overlay: hsla(215, 100%, 65%, 0.4); /* 40% transparent version of motion-primary */

$ui-white: hsla(0, 100%, 100%, 1); /* #FFFFFF */
$ui-white-dim: hsla(0, 100%, 100%, 0.75); /* 25% transparent version of ui-white */
$ui-white-transparent: hsla(0, 100%, 100%, 0.25); /* 25% transparent version of ui-white */
$ui-transparent: hsla(0, 100%, 100%, 0); /* 25% transparent version of ui-white */

$ui-black-transparent: hsla(0, 0%, 0%, 0.15); /* 15% transparent version of black */
$ui-black-transparent-10: hsla(0, 0%, 0%, 0.10); /* 10% transparent version of black */

$ui-black: hsla(0, 0%, 0%, 1); /* #000000 */

$ui-green: hsla(163, 85%, 35%, 1); /* #0DA57A */
$ui-green-2: hsla(163, 85%, 40%, 1); /* #0FBD8C */

$ui-orange: hsla(37, 96%, 55%, 1); /* #FAA51D */
$ui-alert-orange: hsla(32, 100%, 94%, 1); /* #FFF0DF */
$text-primary: hsla(225, 15%, 40%, 1); /* #575E75 */
$text-primary-transparent: hsla(225, 15%, 40%, 0.75);

$motion-primary: hsla(215, 100%, 65%, 1); /* #4C97FF */
$motion-tertiary: hsla(215, 60%, 50%, 1); /* #3373CC */

$looks-secondary: hsla(260, 60%, 60%, 1); /* #855CD6 */
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-tertiary */
$looks-light-transparent: hsla(260, 60%, 60%, 0.15); /* 15% transparent version of looks-tertiary */
$looks-secondary-dark: 	hsla(260, 42%, 51%, 1); /* #714EB6 */

$red-primary: hsla(20, 100%, 55%, 1); /* #FF661A */
$red-tertiary: hsla(20, 100%, 45%, 1); /* #E64D00 */

$sound-primary: hsla(300, 53%, 60%, 1); /* #CF63CF */
$sound-tertiary: hsla(300, 48%, 50%, 1); /* #BD42BD */

$control-primary: hsla(38, 100%, 55%, 1); /* #FFAB19 */

$data-primary: hsla(30, 100%, 55%, 1); /* #FF8C1A */

$pen-primary: hsla(163, 85%, 40%, 1); /* #0FBD8C */
$pen-transparent: hsla(163, 85%, 40%, 0.25); /* #0FBD8C */
$pen-tertiary: hsla(163, 86%, 30%, 1); /* #0B8E69 */

$error-primary: hsla(30, 100%, 55%, 1); /* #FF8C1A */
$error-light: hsla(30, 100%, 70%, 1); /* #FFB366 */
$error-transparent: hsla(30, 100%, 55%, 0.25); /* #FF8C1A */

$extensions-primary: hsla(163, 85%, 40%, 1); /* #0FBD8C */
$extensions-tertiary: hsla(163, 85%, 30%, 1); /* #0B8E69 */
$extensions-transparent: hsla(163, 85%, 40%, 0.35); /* 35% transparent version of extensions-primary */
$extensions-light: hsla(163, 57%, 85%, 1); /* opaque version of extensions-transparent, on white bg */

$membership-blue: hsla(215, 60%, 46%, 1); /* #2F6ABC */
$drop-highlight: hsla(215, 100%, 77%, 1); /* lighter than motion-primary */
/* make sure to keep these in sync with other constants,
e.g. STAGE_DIMENSION_DEFAULTS in lib/screen-utils.js */

$space: 0.5rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 3.125rem;
$library-filter-bar-height: 2.5rem;

$stage-standard-border-width: 0.0625rem;
$stage-full-screen-border-width: 0.1875rem;
$stage-full-screen-stage-padding: 0.1875rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js` */
$full-size: 1095px;
$full-size-paint: 1249px;

$menu-bar-standard-font-size: 0.75rem;
$menu-bar-large-font-size: 0.875rem;
$menu-bar-button-size: 2rem;

$menu-bar-item-max-width: 12rem;
@import "../../css/colors.css";
@import "../../css/units.css";

.modal-content {
    width: 480px;
    line-height: 1.75;
}

.header {
    background-color: $pen-tertiary;
}

.body {
    background: $ui-white;
}

.label {
    font-weight: 500;
    margin: 0 0 0.75rem;
}

.centered-row {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
}

.peripheral-tile-pane {
    overflow-y: auto;
    width: 100%;
    height: 100%;
}

.peripheral-tile {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;

    background-color: $ui-white;
    border-radius: 0.25rem;
    padding: 10px;
    width: 100%;
    height: 55px;
    margin-bottom: 0.5rem;
}

.peripheral-tile-name {
    display: flex;
    align-items: center;
}

[dir="ltr"] .peripheral-tile-image {
    margin-right: 0.5rem;
}

[dir="rtl"] .peripheral-tile-image {
    margin-left: 0.5rem;
}

.peripheral-tile-name-wrapper {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
}

.peripheral-tile-name-label {
    font-weight: bold;
    font-size: 0.625rem;
}

.peripheral-tile-name-text {
    font-size: 0.875rem;
}

.peripheral-tile button {
    padding: 0.6rem 0.75rem;
    border: none;
    border-radius: 0.25rem;
    font-weight: 600;
    font-size: 0.85rem;
    background: $looks-secondary;
    border: $looks-secondary;
    color: white;
    cursor: pointer;
}

.signal-strength-meter {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    width: 22px;
    height: 16px;
}

[dir="ltr"] .signal-strength-meter {
    margin-right: 1rem;
}

[dir="rtl"] .signal-strength-meter {
    margin-left: 1rem;
}

.signal-bar {
    width: 4px;
    border-radius: 4px;
    background-color: #DBDBDB;
}

.signal-bar:nth-of-type(1) { height: 25%; }
.signal-bar:nth-of-type(2) { height: 50%; }
.signal-bar:nth-of-type(3) { height: 75%; }
.signal-bar:nth-of-type(4) { height: 100%; }

.green-bar {
    background-color: $pen-primary;
}

.radar-small {
    width: 40px;
    height: 40px;
}

[dir="ltr"] .radar-small {
    margin-right: 0.5rem;
}

[dir="rtl"] .radar-small {
    margin-left: 0.5rem;
}

.radar-big {
    width: 120px;
    height: 120px;
}

.radar-spin {
    animation: spin 4s linear infinite;
}

[dir="ltr"] .radar {
    margin-right: .5rem;
}

[dir="rtl"] .radar {
    margin-left: .5rem;
}

@keyframes spin {
    100% {
        transform: rotate(360deg);
    }
}

.peripheral-activity {
    position: relative;
}

.peripheral-activity-icon {
    /* width: 80px;
    height: 80px; */
}

.connection-tip-icon {
    position: absolute;
}

.bluetooth-connecting-icon {
    position: absolute;
    top: -5px;
    right: -15px;
    left: -15px;
    padding: 5px 5px;
    background-color: $looks-secondary;
    border-radius: 100%;
    box-shadow: 0px 0px 0px 4px $looks-transparent;
    /* animation: pulse-blue-ring 1s infinite ease-in-out alternate; */
    animation: wiggle 0.5s infinite ease-in-out alternate;

}

@keyframes pulse-blue-ring {
    100% {
        box-shadow: 0px 0px 0px 8px $looks-light-transparent;
    }
}

.bluetooth-connected-icon {
    position: absolute;
    top: -5px;
    right: -15px;
    left: -15px;
    padding: 5px 5px;
    background-color: $pen-primary;
    border-radius: 100%;
    box-shadow: 0px 0px 0px 4px $pen-transparent;
}

@keyframes wiggle {
    0% {transform: rotate(3deg) scale(1.05);}
    25% {transform: rotate(-3deg) scale(1.05);}
    50% {transform: rotate(5deg) scale(1.05);}
    75% {transform: rotate(-2deg) scale(1.05);}
    100% {transform: rotate(0deg) scale(1.05);}
}

.bluetooth-centered-icon {
    position: absolute;
    padding: 5px 5px;
    background-color: $looks-secondary;
    border-radius: 100%;
    box-shadow: 0px 0px 0px 2px $looks-transparent;
}

.peripheral-tile-widgets {
    display: flex;
    align-items: center;
}

.activityArea {
    height: 165px;
    background-color: $looks-light-transparent;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: .5rem;
}

.scratch-link-help {
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    height: 100%;
    padding-top: .5rem;
    padding-bottom: .5rem;
}

.scratch-link-help-step {
    display: flex;
    flex-direction: row;
    justify-content: flex-start;
    align-items: center;
}

[dir="ltr"] .scratch-link-help-step {
    margin-left: 2.5rem;
}

[dir="rtl"] .scratch-link-help-step {
    margin-right: 2.5rem;
}

.scratch-link-icon {
    max-width: 50px;
}

.help-step-image {
    max-width: 40px;
}

[dir="ltr"] .help-step-image {
    margin-right: 0.5rem;
}

[dir="rtl"] .help-step-image {
    margin-left: 0.5rem;
}

.help-step-number {
    background: $pen-tertiary;
    border-radius: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    color: $ui-white;
    font-weight: bold;
    min-width: 2rem;
    height: 2rem;
}

[dir="ltr"] .help-step-number {
    margin-right: 0.5rem;
}

[dir="rtl"] .help-step-number {
    margin-left: 0.5rem;
}

.button-row {
    font-weight: bolder;
    text-align: center;
    display: flex;
}

.abort-connecting-icon {
    width: 10px;
    transform: rotate(45deg);
}

.connection-button {
    padding: 0.6rem 0.75rem;
    border-radius: 0.5rem;
    background: $looks-secondary;
    color: white;
    font-weight: 600;
    font-size: 0.85rem;
    margin: 0.25rem;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
}

.connection-button:disabled {
    background: $looks-transparent;
}

.segmented-button {
    display: flex;
}

.segmented-button .connection-button:first-of-type {
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
    margin-right: 0;
}

.segmented-button .connection-button:last-of-type {
    margin-left: 1px;
    border-top-left-radius: 0;
    border-bottom-left-radius: 0;
}

[dir="ltr"] .button-icon-right {
    margin-left: 0.5rem;
}
[dir="rtl"] .button-icon-right {
    margin-right: 0.5rem;
}

[dir="ltr"] .button-icon-left {
    margin-right: 0.5rem;
}

[dir="rtl"] .button-icon-left {
    margin-left: 0.5rem;
}

/* reverse back arrow icon for RTL, don't reverse other connection icons */
[dir="rtl"] .button-icon-back {
    transform: scaleX(-1);
}

.red-button {
    background: $red-primary;
}

.corner-buttons {
    display: flex;
    justify-content: space-between;
    width: 100%;
    padding: 0 1rem;
}

.bottom-area {
    background-color: $ui-white;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 1rem;
    padding-bottom: .75rem;
    padding-left: .75rem;
    padding-right: .75rem;
}

.bottom-area .bottom-area-item+.bottom-area-item {
    margin-top: 1rem;
}

.instructions {
    text-align: center;
}

.dots-row {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
}

.dots-holder {
    display: flex;
    padding: 0.25rem 0.1rem;
    border-radius: 1rem;
    background: $looks-light-transparent;
}

.dots-holder-success {
    background: $pen-transparent;
}

.dots-holder-error {
    background: $error-transparent;
}

.dot {
    width: 0.5rem;
    height: 0.5rem;
    margin: 0 0.3rem;
    border-radius: 100%;
}

.inactive-step-dot {
    background: $looks-transparent;
}

.active-step-dot {
    background: $looks-secondary;
}

.success-dot {
    background: $pen-primary;
}

.error-dot {
    background: $error-primary;
}

.scratch-link-error {
    align-items: center;
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    height: 100%;
    padding-top: .5rem;
    padding-bottom: .5rem;
    width: 90%;
}

.scratch-link-error-details {
    display: flex;
    resize: none;
    height: 60%;
    width: inherit;
}
